# Hypothesis: fill Moore-neighborhood of markers with 3 (preserving markers themselves)

def transform(grid):
    h, w = len(grid), len(grid[0])
    result = [row[:] for row in grid]

    # Find all marker positions
    markers = [(r,c) for r in range(h) for c in range(w) if grid[r][c] != grid[h//2][0]]

    for r,c in markers:
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                nr, nc = r+dr, c+dc
                if 0 <= nr < h and 0 <= nc < w:
                    val = grid[nr][nc]
                    # Preserve markers, background stays, other cells become 3
                    if val != grid[0][0] and not ((nr==r and nc==c)):
                        result[nr][nc] = 3

    return result

