# Flood fill from outside to determine enclosed regions

def is_enclosed(grid):
    """Flood fill from top-left corner; cells not reached are enclosed"""
    h, w = len(grid), len(grid[0])
    bg = grid[0][0]

    visited = set()
    stack = [(0, 0)]
    visited.add((0, 0))

    while stack:
        r, c = stack.pop()
        for dr, dc in [(-1,0),(1,0),(0,-1),(0,1)]:
            nr, nc = r+dr, c+dc
            if 0 <= nr < h and 0 <= nc < w and (nr,nc) not in visited:
                if grid[nr][nc] == bg:
                    visited.add((nr, nc))
                    stack.append((nr, nc))

    # Cells not visited and not markers are enclosed
    enclosed = set()
    for r in range(h):
        for c in range(w):
            if (r,c) not in visited and grid[r][c] != bg:
                enclosed.add((r,c))

    return enclosed

