# Try 8-connectivity flood fill from outside

def is_enclosed_8conn(grid):
    """Flood fill from outside using 8-connectivity; cells not reached are enclosed"""
    h, w = len(grid), len(grid[0])
    bg = grid[0][0]

    visited = set()
    stack = [(0, 0)]
    visited.add((0, 0))

    while stack:
        r, c = stack.pop()
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                if dr == 0 and dc == 0:
                    continue
                nr, nc = r+dr, c+dc
                if 0 <= nr < h and 0 <= nc < w and (nr,nc) not in visited:
                    if grid[nr][nc] == bg:
                        visited.add((nr, nc))
                        stack.append((nr, nc))

    # Cells not visited but not markers - these should be "inside" enclosures
    enclosed_bg = set()
    enclosed_markers = set()
    for r in range(h):
        for c in range(w):
            if (r,c) not in visited:
                if grid[r][c] == bg:
                    enclosed_bg.add((r,c))
                else:
                    enclosed_markers.add((r,c))

    return enclosed_bg | enclosed_markers

