# Check: if we treat markers as blocking diagonal passage too, what gets enclosed?

def is_enclosed_blocked_diagonal(grid):
    """Flood fill with BOTH orthogonal AND diagonal passing blocked by non-bg"""
    h, w = len(grid), len(grid[0])
    bg = grid[0][0]

    visited = set()
    # Start from corners - if they're reachable, everything connected to them is "outside"
    for start_r, start_c in [(0,0), (0,w-1), (h-1,0), (h-1,w-1)]:
        stack = [(start_r, start_c)]
        visited.add((start_r, start_c))

        while stack:
            r, c = stack.pop()
            # Try orthogonal movement
            for dr, dc in [(-1,0),(1,0),(0,-1),(0,1)]:
                nr, nc = r+dr, c+dc
                if 0 <= nr < h and 0 <= nc < w and (nr,nc) not in visited:
                    if grid[nr][nc] == bg:
                        visited.add((nr, nc))
                        stack.append((nr, nc))

    # Now find all bg cells not reachable
    enclosed_bg = {(r,c) for r in range(h) for c in range(w) if grid[r][c] == bg and (r,c) not in visited}
    return enclosed_bg

