# Let's see the bounding box of each marker cluster

def find_marker_clusters(grid):
    """Find connected clusters of markers using 8-connectivity"""
    h, w = len(grid), len(grid[0])
    bg = grid[0][0]

    visited = set()
    clusters = []

    for r in range(h):
        for c in range(w):
            if grid[r][c] != bg and (r,c) not in visited:
                # Start BFS/DFS to find connected cluster
                cluster = [(r,c)]
                stack = [(r,c)]
                while stack:
                    curr_r, curr_c = stack.pop()
                    for dr in [-1, 0, 1]:
                        for dc in [-1, 0, 1]:
                            if dr == 0 and dc == 0:
                                continue
                            nr, nc = curr_r+dr, curr_c+dc
                            if 0 <= nr < h and 0 <= nc < w and grid[nr][nc] != bg and (nr,nc) not in visited:
                                visited.add((nr,nc))
                                cluster.append((nr,nc))
                                stack.append((nr,nc))
                clusters.append(cluster)

    return clusters

