# Check distance from markers for cells that become 3

def dist_to_nearest_marker(pos, grid):
    r,c = pos
    h,w = len(grid), len(grid[0])
    min_dist = float('inf')

    for i in range(h):
        for j in range(w):
            if grid[i][j] != grid[0][0]:
                d = abs(i-r) + abs(j-c)
                min_dist = min(min_dist, d)
    return min_dist

