# Hypothesis: Fill background cells horizontally between markers on the same row

def predict_horizontal_gaps_only(grid):
    h, w = len(grid), len(grid[0])
    bg = grid[0][0]

    predicted = [[grid[r][c] for c in range(w)] for r in range(h)]

    for r in range(h):
        marker_cols = [c for c in range(w) if grid[r][c] != bg]

        for i in range(len(marker_cols)):
            # Gap before first marker? Skip - doesn't seem to get filled
            if i == 0:
                continue
            prev_marker = marker_cols[i-1]
            curr_marker = marker_cols[i]

