            queue.append((r, 0))
            visited.add((r, 0))
        if grid[r][w-1] == bg:
            queue.append((r, w-1))
            visited.add((r, w-1))

    while queue:
        r, c = queue.pop(0)
        for dr, dc in [(-1,0),(1,0),(0,-1),(0,1)]:
            nr, nc = r+dr, c+dc
            if 0 <= nr < h and 0 <= nc < w and grid[nr][nc] == bg and (nr,nc) not in visited:
