# Try: only direct adjacent pairs fill, plus propagation

def predict_adjacent_propagate(grid):
    """Direct adjacent-only + propagate through filled cells"""
    h, w = len(grid), len(grid[0])
    bg = grid[0][0]

    result = [[grid[r][c] for c in range(w)] for r in range(h)]

    # Multiple passes
    for iteration in range(h + w):
        prev_fill_count = sum(3 for row in result for cell in row if cell == 3)

        # Horizontal: only consecutive markers on same row
        for r in range(h):
            special_cells = sorted([c for c in range(w) if result[r][c] != bg])
            for i in range(len(special_cells) - 1):
                mc1, mc2 = special_cells[i], special_cells[i+1]
                for c in range(mc1 + 1, mc2):
                    if result[r][c] == bg:
                        result[r][c] = 3

        # Vertical: only consecutive markers in same column  
        for c in range(w):
            special_rows = sorted([r for r in range(h) if result[r][c] != bg])
            for i in range(len(special_rows) - 1):
                top_r, bottom_r = special_rows[i], special_rows[i+1]
                for r in range(top_r + 1, bottom_r):
                    if result[r][c] == bg:
                        result[r][c] = 3

        # Check if any cells became non-bg (markers or 3s)
        new_3_count = sum(3 for row in result for cell in row if cell == 3)
        if new_3_count == prev_fill_count:
            break

    return result

